-- Deal Control Center foundation: controlled lifecycle, approval, shipment handover and audit.
create table if not exists public.deal_events(id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id) on delete cascade,event_type text not null,from_value text,to_value text,reason text,metadata jsonb not null default '{}'::jsonb,performed_by uuid references public.profiles(id),created_at timestamptz not null default now());
alter table public.deal_events enable row level security;
create index if not exists idx_deal_events_deal_created on public.deal_events(deal_id,created_at desc);
drop policy if exists deal_events_read_authenticated on public.deal_events; create policy deal_events_read_authenticated on public.deal_events for select to authenticated using(true);
create or replace function public.deal_current_role() returns text language sql stable security definer set search_path=public as $$select coalesce((select role::text from public.profiles where id=auth.uid() and active=true limit 1),'unknown')$$;
create or replace function public.deal_can_write() returns boolean language sql stable security definer set search_path=public as $$select public.deal_current_role() in ('admin','ceo','manager','dealer')$$;
create or replace function public.deal_can_approve() returns boolean language sql stable security definer set search_path=public as $$select public.deal_current_role() in ('admin','ceo','manager')$$;
revoke all on function public.deal_current_role() from public,anon; revoke all on function public.deal_can_write() from public,anon; revoke all on function public.deal_can_approve() from public,anon; grant execute on function public.deal_current_role() to authenticated,service_role; grant execute on function public.deal_can_write() to authenticated,service_role; grant execute on function public.deal_can_approve() to authenticated,service_role;
create or replace function public.deal_creation_integrity_guard() returns trigger language plpgsql set search_path=public as $$begin if current_user not in ('postgres','service_role') then new.status:='draft'::deal_status;new.payment_status:='Pending';new.shipment_status:='Planning';if public.deal_current_role()='dealer' then new.dealer_id:=auth.uid();end if;end if;return new;end$$;
drop trigger if exists trg_deal_creation_integrity on public.deals; create trigger trg_deal_creation_integrity before insert on public.deals for each row execute function public.deal_creation_integrity_guard();
create or replace function public.deal_sensitive_update_guard() returns trigger language plpgsql set search_path=public as $$begin if current_user not in ('postgres','service_role') and (new.status is distinct from old.status or new.payment_status is distinct from old.payment_status or new.shipment_status is distinct from old.shipment_status or new.dealer_id is distinct from old.dealer_id) then raise exception 'Deal lifecycle, owner, payment and shipment state must use controlled workflows.';end if;return new;end$$;
drop trigger if exists trg_deal_sensitive_update_guard on public.deals; create trigger trg_deal_sensitive_update_guard before update on public.deals for each row execute function public.deal_sensitive_update_guard();
create or replace function public.deal_request_readiness_check_v1(p_deal_id uuid) returns boolean language plpgsql security definer set search_path=public as $$declare d public.deals; cs text; ss text; k text; exp date;begin select * into d from public.deals where id=p_deal_id;if not found then raise exception 'Deal not found.';end if;if coalesce(d.amount,0)<=0 then raise exception 'Deal amount must be greater than zero.';end if;if d.customer_id is null then raise exception 'Customer is required.';end if;select status into cs from public.customers where id=d.customer_id;if cs<>'active' then raise exception 'Customer must be active.';end if;if d.supplier_id is not null then select status,kyc_status,kyc_expiry_date into ss,k,exp from public.suppliers where id=d.supplier_id;if ss<>'active' then raise exception 'Supplier must be active.';end if;if coalesce(k,'pending')<>'approved' or exp is null or exp<current_date then raise exception 'Supplier KYC must be approved and valid.';end if;end if;return true;end$$;
create or replace function public.deal_request_approval_v1(p_deal_id uuid,p_comments text default null) returns public.approvals language plpgsql security definer set search_path=public as $$declare r text:=public.deal_current_role();d public.deals;a public.approvals;begin if r not in ('admin','ceo','manager','dealer') then raise exception 'Deal approval request is not permitted for this role.';end if;select * into d from public.deals where id=p_deal_id for update;if not found then raise exception 'Deal not found.';end if;if r='dealer' and d.dealer_id is distinct from auth.uid() then raise exception 'Dealer users may only submit their own deals.';end if;if d.status not in ('draft','review') then raise exception 'Only draft or review deals can be submitted for approval.';end if;perform public.deal_request_readiness_check_v1(p_deal_id);if exists(select 1 from public.approvals where entity_type='deal' and entity_id=p_deal_id and status='pending') then raise exception 'A pending approval already exists for this deal.';end if;insert into public.approvals(entity_type,entity_id,approval_type,requested_by,status,comments) values('deal',p_deal_id,'commercial',auth.uid(),'pending',nullif(trim(coalesce(p_comments,'')),'')) returning * into a;update public.deals set status='pending',updated_at=now() where id=p_deal_id;insert into public.deal_events(deal_id,event_type,from_value,to_value,reason,performed_by) values(p_deal_id,'approval_requested',d.status::text,'pending',nullif(trim(coalesce(p_comments,'')),''),auth.uid());return a;end$$;
create or replace function public.deal_decide_approval_v1(p_approval_id uuid,p_decision text,p_comments text default null) returns public.approvals language plpgsql security definer set search_path=public as $$declare a public.approvals;d public.deals;dst deal_status;begin if not public.deal_can_approve() then raise exception 'Deal approval decision requires manager-level permission.';end if;if p_decision not in ('approved','rejected') then raise exception 'Decision must be approved or rejected.';end if;if p_decision='rejected' and length(trim(coalesce(p_comments,'')))<5 then raise exception 'Rejection requires a reason of at least 5 characters.';end if;select * into a from public.approvals where id=p_approval_id and entity_type='deal' for update;if not found or a.status<>'pending' then raise exception 'Pending deal approval not found.';end if;select * into d from public.deals where id=a.entity_id for update;if p_decision='approved' then perform public.deal_request_readiness_check_v1(d.id);dst:='approved';else dst:='draft';end if;update public.approvals set status=p_decision,comments=nullif(trim(coalesce(p_comments,'')),''),approver_id=auth.uid(),decided_at=now() where id=p_approval_id returning * into a;update public.deals set status=dst,updated_at=now() where id=d.id;insert into public.deal_events(deal_id,event_type,from_value,to_value,reason,performed_by) values(d.id,case when p_decision='approved' then 'approval_approved' else 'approval_rejected' end,d.status::text,dst::text,nullif(trim(coalesce(p_comments,'')),''),auth.uid());return a;end$$;
create or replace function public.deal_create_shipment_v1(p_deal_id uuid) returns public.shipments language plpgsql security definer set search_path=public as $$declare r text:=public.deal_current_role();d public.deals;sh public.shipments;no text;begin if r not in ('admin','ceo','manager','dealer','logistics','operations') then raise exception 'Shipment handover is not permitted for this role.';end if;select * into d from public.deals where id=p_deal_id for update;if not found then raise exception 'Deal not found.';end if;if r='dealer' and d.dealer_id is distinct from auth.uid() then raise exception 'Dealer users may only hand over their own deals.';end if;if d.status<>'approved' then raise exception 'Deal must be approved before shipment handover.';end if;perform public.deal_request_readiness_check_v1(p_deal_id);no:='SHP-'||to_char(now(),'YYYYMMDD')||'-'||right(replace(gen_random_uuid()::text,'-',''),6);insert into public.shipments(shipment_no,deal_id,quotation_id,customer_id,supplier_id,status,origin,destination,cargo_description,currency,owner_id,created_by) values(no,d.id,d.quotation_id,d.customer_id,d.supplier_id,'planning',d.origin_country,d.destination_country,coalesce(d.commodity,d.notes),coalesce(d.sell_currency,'AED'),d.dealer_id,auth.uid()) returning * into sh;insert into public.deal_events(deal_id,event_type,to_value,metadata,performed_by) values(d.id,'shipment_created',sh.shipment_no,jsonb_build_object('shipment_id',sh.id),auth.uid());return sh;end$$;
create or replace function public.deal_cancel_v1(p_deal_id uuid,p_reason text) returns public.deals language plpgsql security definer set search_path=public as $$declare r text:=public.deal_current_role();d public.deals;begin if r not in ('admin','ceo','manager','dealer') then raise exception 'Deal cancellation is not permitted for this role.';end if;if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Cancellation reason must contain at least 5 characters.';end if;select * into d from public.deals where id=p_deal_id for update;if not found then raise exception 'Deal not found.';end if;if r='dealer' and (d.dealer_id is distinct from auth.uid() or d.status not in ('draft','review')) then raise exception 'Dealer users may cancel only their own draft/review deals.';end if;if d.status='completed' then raise exception 'Completed deals cannot be cancelled.';end if;update public.deals set status='cancelled',updated_at=now() where id=p_deal_id returning * into d;insert into public.deal_events(deal_id,event_type,to_value,reason,performed_by) values(d.id,'cancelled','cancelled',trim(p_reason),auth.uid());return d;end$$;
revoke all on function public.deal_request_readiness_check_v1(uuid) from public,anon;revoke all on function public.deal_request_approval_v1(uuid,text) from public,anon;revoke all on function public.deal_decide_approval_v1(uuid,text,text) from public,anon;revoke all on function public.deal_create_shipment_v1(uuid) from public,anon;revoke all on function public.deal_cancel_v1(uuid,text) from public,anon;grant execute on function public.deal_request_readiness_check_v1(uuid),public.deal_request_approval_v1(uuid,text),public.deal_decide_approval_v1(uuid,text,text),public.deal_create_shipment_v1(uuid),public.deal_cancel_v1(uuid,text) to authenticated,service_role;
